import { http } from './transport';
export function fetchLedger() { return http.get('/purchase/ledger'); }
export function fetchSummary() { return http.graphql(`query PurchaseSummary { purchaseSummary { count } }`); }
export function dynamicRequest() { return http.get('/purchase/' + globalThis.target); }

import Ledger from './pages/Ledger';
export const router = { id: 'main', mode: 'hash' };
export const routes = [{ path: '/Other/purchaseLedger', alias: '/purchase', titleKey: 'purchase.title', component: Ledger }];

import { fetchLedger, fetchSummary, dynamicRequest } from '../requests';
/** 采购台账：供应商筛选。 */
export function Ledger() {
  async function query() { return fetchLedger(); }
  async function summary() { return fetchSummary(); }
  return <section><button onClick={query}>查询</button><button onClick={summary}>汇总</button><button onClick={dynamicRequest}>动态查询</button></section>;
}
export default Ledger;

import { query } from './workers';
export const moduleInfo = { key: 'purchase', name: '采购模块' };
scheduler.register('nightly-ledger', query);
messages.subscribe('purchase.refresh', query);
commands.register('refresh-ledger', query);
